"""Writes docs/CENSUS_DAY_1998.md from the census-day layer outputs (build/14 and build/16), so that every number
in the note is read from the files."""
import pandas as pd, numpy as np, json
OUT='output/'
U=pd.read_csv(OUT+'unit_master_1998census_all.csv'); X=pd.read_csv(OUT+'crosswalk_tehsil_1998census_to_pcoframe.csv')
G=pd.read_csv(OUT+'crosswalk_tehsil_1998census_to_2023.csv'); D=pd.read_csv(OUT+'crosswalk_district_1998census_to_pcoframe.csv')
m=pd.read_csv('build/intermediate/unit_master_1998_solved_frame.csv')
S=json.load(open(OUT+'validation_summary_censusday.json'))
def t(s): return s.replace(' DISTRICT','').title().replace('D.I.Khan','D.I.Khan').replace('D.G.Khan','D.G.Khan')
L=['# The census-day 1998 frame (1 March 1998) and the report frame\n',
   f"Fourth release, {pd.Timestamp.today():%d %B %Y}. Generated by build/17_census_day_report.py from the files it describes.\n",
   '## 1. Why there are two 1998 frames',
   'The digital source for the 1998 census used in this project (the PBS web table of *Population of Administrative Units 1951-98*, parsed by Data Darbar) is the report as re-issued on the administrative map of the mid-2000s: it carries the 1998 counts, but on tehsils and districts that were created after the census (for example Nushki district, Talhar, Lachi, Naurang, Sohbatpur and Daraban tehsils) and without ones that existed on census day (Umerkot district, the five Karachi districts). The scanned Census Publication 161 (Population Census Organisation, January 2002; raw/census1998_frames/national/) prints the same census on the units as they stood on census day. The Punjab Government published its own census-day table (build/14). This release transcribes Tables 2, 3, 5 and 6 of the scan (NWFP, FATA, Sindh, Balochistan) by hand from the page images, checks every province, division and district sum, and links the census-day units to the report frame and on to 2023.\n',
   '## 2. The census-day frame',
   f"{len(U)} sub-district units in {U.district_1998census.nunique()} districts and agencies: "+', '.join(f"{(p if p=='FATA' else p.title())} {n}" for p,n in U.province.value_counts().items())+
   f". Population {int(U.pop_1998census.sum()):,}, equal to the report frame's {int(m.pop_1998.sum()):,}. Karachi's five census-day districts (East, West, South, Central, Malir) enter as five units; the report lists Karachi as one unit, so they map to it. The six Frontier Regions are single units in both frames. Balochistan's table is nested (district, sub-division, tehsil or sub-tehsil); the leaf units are used and the sub-division is kept as a column. Quetta Tehsil is printed in two parts, one under each sub-division, and both parts are kept.",
   'Besides the 1998 count, Publication 161 prints the 1951, 1961, 1972 and 1981 populations restated on each census-day unit, and the area; these columns are carried in unit_master_1998census_all.csv for the four transcribed provinces (not for Punjab, whose source table has 1998 only). Transcriptions: raw/census1998_frames/transcribed/*.csv (one row per printed line, with page number and footnote marks).\n',
   '## 3. Linking census-day units to the report frame',
   f"crosswalk_tehsil_1998census_to_pcoframe.csv: {len(X)} rows; {S['tehsil_confidence'].get('high',0)} high, {S['tehsil_confidence'].get('medium',0)} medium, {S['tehsil_confidence'].get('low',0)} low; {int((X.groupby('unit_id_1998census').size()>1).sum())} census-day units split across report-frame units. Same resolver as every other layer (build/crosswalk_lib.py): same-named pairs with identical populations are pinned, the remaining flows are chosen to balance both frames while opening as few links as possible, with adjacency (from the 2023 polygons each report-frame unit flows into) as the tie-breaker, and every opened link graded by whether the tables can balance without it. Weights and totals are checked in the build (validation_summary_censusday.json).",
   'Chained to 2023: crosswalk_tehsil_1998census_to_2023.csv, '+f"{len(G)} rows ({S['chained_confidence'].get('high',0)} high, {S['chained_confidence'].get('medium',0)} medium, {S['chained_confidence'].get('low',0)} low), population and area weights, every weight set summing to one; crosswalk_district_1998census_to_pcoframe.csv and crosswalk_district_1998census_to_2023.csv at district level.\n",
   '## 4. Where the two frames differ at district level',
   'Every district whose census-day population is not fully inside the same report-frame district (persons moving, census-day count, share):\n',
   '| Census-day district | Report-frame district | Persons | Share | Grade |','|---|---|---|---|---|']
for _,r in D[(D.pop_weight<1)&(D.district_1998census!=D.district_1998_pcoframe)].sort_values(['province','district_1998census']).iterrows():
    L.append(f"| {t(r.district_1998census)} ({r.province.title()}) | {t(r.district_1998_pcoframe)} | {int(r.flow_1998):,} | {r.pop_weight:.1%} | {r.confidence} |")
kar=D[D.district_1998census.str.startswith(('KARACHI','MALIR'))]
L.append(f"\nPlus the five Karachi districts ({', '.join(t(x) for x in kar.district_1998census)}; {int(kar.flow_1998.sum()):,} persons) into the single Karachi unit, and Umerkot (663,095) into Mirpur Khas, both whole.\n")
L.append('Read unit by unit in the tehsil file, the district transfers are: Nushki tehsil out of Chagai (the report frame lists Nushki as a district), Lehri tehsil from Bolan to Sibi, Sinjawi from Loralai to Ziarat, part of Gulistan to Pishin, part of Dasht (Mastung) to Quetta, parts of Kashmor, Khangarh and Tando Muhammad Khan talukas to the neighbouring district, and part of Shahdadpur to Nawabshah. These are the administrative changes made between census day and the map the report frame uses. The event register (docs/EVENT_REGISTER.md) dates those that could be sourced; PCO\'s own register of changes between 1981 and 1998 is Annexures A to D of the same publication (text extract in raw/census1998_frames/national/).\n')
L.append('## 5. Within-district differences')
w=X[(X.district_1998census==X.district_1998_pcoframe)&(X.method!='one_to_one')&(X.province!='PUNJAB')]
L.append(f"{w.unit_id_1998census.nunique()} census-day units outside Punjab changed within their district (tehsils created after the census or boundaries moved): "+'; '.join(f"{t(d)}: "+', '.join(sorted(set(t(u) for u in g.unit_1998census))) for d,g in w.groupby('district_1998census'))+'. Punjab\'s nine are listed in build/14 and docs/BACKWARD_EXTENSION.md.\n')
L.append('## 6. What is still graded medium or low, and why')
nh=X[X.confidence!='high']
for d,g in nh.groupby('district_1998census'):
    L.append(f"- {t(d)} ({g.province.iloc[0].title()}): "+'; '.join(f"{t(r.unit_1998census)} -> {t(r.unit_1998_pcoframe)} {int(r.flow_1998):,} ({r.confidence})" for _,r in g.iterrows()))
L.append('\nA medium row means the tables balance another way too, but less plausibly given adjacency; a low row means an equally plausible alternative exists (the note column names the cell cost). A user who needs one of these cases settled should look for the provincial notification that created or moved the tehsil (the event register has the ones found so far), and can override any row by editing the flow column, since the apply functions only require weights to sum to one.\n')
L.append('## 7. Files')
L.append('unit_master_1998census_all.csv (unit id, province, district, unit, sub-division where printed, 1998 population and area, 1951-1981 restated populations, source table and page), crosswalk_tehsil_1998census_to_pcoframe.csv, crosswalk_tehsil_1998census_to_2023.csv, crosswalk_district_1998census_to_pcoframe.csv, crosswalk_district_1998census_to_2023.csv, validation_summary_censusday.json. Unit ids are T98C-<province>-nnn (PB, SD, KP, FA, BA). The Punjab-only files from the third release (…_punjab.csv) are unchanged and are contained in the all-province files.')
open('docs/CENSUS_DAY_1998.md','w').write('\n'.join(L)+'\n'); print('wrote docs/CENSUS_DAY_1998.md')
